function bytes(b64) {
  const bin = atob(b64);
  const a = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
  return a;
}

const CACHE = new Map();
function serve(key, b64, type) {
  if (!CACHE.has(key)) CACHE.set(key, bytes(b64));
  return new Response(CACHE.get(key), {
    headers: { "content-type": type, "cache-control": "public, max-age=604800, immutable" },
  });
}

export function ogImage() { return serve("og", OG, "image/jpeg"); }
export function appIcon() { return serve("i180", I180, "image/png"); }
export function icon192() { return serve("i192", I192, "image/png"); }
export function icon512() { return serve("i512", I512, "image/png"); }
export function iconMaskable() { return serve("imsk", IMSK, "image/png"); }
